let language = localStorage.getItem("threeRootsLanguage") || "en";
let activeProduct = "mad";
let activeFilter = "all";

const filterCopyKeys = {
  all: "filterAll",
  conditioner: "filterConditioners",
  maintenance: "filterMaintenance",
  performance: "filterPerformance",
  scratch: "filterScratch"
};

function visibleProductIds() {
  return productOrder.filter((id) => activeFilter === "all" || products[id].group === activeFilter);
}

function renderProductTabs() {
  const ids = visibleProductIds();
  if (!ids.includes(activeProduct)) activeProduct = ids[0];
  const selector = document.getElementById("feed-selector");
  selector.innerHTML = ids.map((id) => {
    const product = products[id];
    const selected = id === activeProduct;
    return `<button class="feed-tab${selected ? " active" : ""}" id="tab-${id}" role="tab" aria-selected="${selected}" aria-controls="feed-panel" tabindex="${selected ? "0" : "-1"}" data-product="${id}"><img src="${product.image}" alt="" loading="lazy"><span><small>${product.tab[language]}</small><strong>${product.name.toUpperCase()}</strong></span></button>`;
  }).join("");

  document.querySelectorAll(".catalog-filter").forEach((button) => {
    const selected = button.dataset.filter === activeFilter;
    button.classList.toggle("active", selected);
    button.setAttribute("aria-pressed", selected ? "true" : "false");
  });

  const filterLabel = copy[language][filterCopyKeys[activeFilter]];
  document.getElementById("catalog-status").textContent = language === "en"
    ? `Showing ${ids.length} ${copy.en.formulaCount}${activeFilter === "all" ? "" : ` · ${filterLabel}`}`
    : `Mostrando ${ids.length} ${copy.es.formulaCount}${activeFilter === "all" ? "" : ` · ${filterLabel}`}`;
}

function renderInterestOptions() {
  const select = document.getElementById("interest-select");
  const current = select.value;
  select.replaceChildren(...productOrder.map((id) => {
    const option = document.createElement("option");
    option.value = id;
    option.textContent = products[id].name;
    return option;
  }));
  const allStock = document.createElement("option");
  allStock.value = "allstock";
  allStock.textContent = "All Stock Sweet 14%";
  select.append(allStock);
  const dealer = document.createElement("option");
  dealer.value = "dealer";
  dealer.textContent = copy[language].dealerOption;
  select.append(dealer);
  select.value = productOrder.includes(current) || current === "allstock" || current === "dealer" ? current : activeProduct;
}

function setLanguage(lang) {
  language = lang;
  localStorage.setItem("threeRootsLanguage", lang);
  document.documentElement.lang = lang;
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const value = copy[lang][el.dataset.i18n];
    if (value !== undefined) el.innerHTML = value;
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
    el.placeholder = copy[lang][el.dataset.i18nPlaceholder] || "";
  });
  document.querySelectorAll("[data-i18n-aria-label]").forEach((el) => {
    el.setAttribute("aria-label", copy[lang][el.dataset.i18nAriaLabel] || "");
  });
  const toggle = document.querySelector(".language-toggle");
  toggle.innerHTML = lang === "en" ? '<span class="lang-active">EN</span><span aria-hidden="true">/</span><span>ES</span>' : '<span>EN</span><span aria-hidden="true">/</span><span class="lang-active">ES</span>';
  toggle.setAttribute("aria-label", lang === "en" ? "Cambiar a español" : "Switch to English");
  renderProductTabs();
  renderInterestOptions();
  updateProduct(activeProduct);
}

function updateProduct(id) {
  activeProduct = id;
  const product = products[id];
  const data = product[language];
  const image = document.getElementById("feed-image");
  image.src = product.image;
  image.alt = language === "en" ? `${product.name} colorful feed blend` : `Mezcla colorida ${product.name}`;
  const productIndex = productOrder.indexOf(id) + 1;
  document.getElementById("feed-number").textContent = `${String(productIndex).padStart(2, "0")} / ${productOrder.length}`;
  document.getElementById("feed-category").textContent = data.category;
  document.getElementById("feed-name").textContent = product.name;
  document.getElementById("feed-tagline").textContent = data.tagline;
  document.getElementById("feed-description").textContent = data.description;
  const hasListedWeight = Boolean(product.weight);
  document.getElementById("feed-weight").textContent = hasListedWeight ? product.weight : copy[language].notListed;
  document.getElementById("feed-weight-unit").hidden = !hasListedWeight;
  document.getElementById("feed-weight-wrap").classList.toggle("not-listed", !hasListedWeight);
  document.getElementById("feed-protein").textContent = product.protein;
  document.getElementById("feed-fat").textContent = product.fat;
  document.getElementById("feed-fiber").textContent = product.fiber;
  document.getElementById("feed-ingredients").textContent = data.ingredients;
  document.getElementById("product-chips").innerHTML = data.chips.map((chip) => `<span>${chip}</span>`).join("");
  document.getElementById("spec-dialog-title").textContent = product.name;
  document.getElementById("modal-protein").textContent = product.protein;
  document.getElementById("modal-fat").textContent = product.fat;
  document.getElementById("modal-fiber").textContent = product.fiber;
  document.getElementById("modal-weight").textContent = hasListedWeight ? `${product.weight} ${language === "en" ? "LBS" : "LB"}` : copy[language].notListed;
  document.getElementById("modal-ingredients").textContent = data.ingredients;
  document.querySelectorAll(".feed-tab").forEach((tab) => {
    const selected = tab.dataset.product === id;
    tab.classList.toggle("active", selected);
    tab.setAttribute("aria-selected", selected ? "true" : "false");
    tab.tabIndex = selected ? 0 : -1;
  });
  const interest = document.getElementById("interest-select");
  if (interest && interest.value !== "dealer") interest.value = id;
}

const header = document.querySelector(".site-header");
addEventListener("scroll", () => header.classList.toggle("scrolled", scrollY > 24), { passive: true });

const menuToggle = document.querySelector(".menu-toggle");
const nav = document.querySelector(".site-nav");
menuToggle.addEventListener("click", () => {
  const open = menuToggle.getAttribute("aria-expanded") === "true";
  menuToggle.setAttribute("aria-expanded", String(!open));
  nav.classList.toggle("open", !open);
});
nav.querySelectorAll("a").forEach((link) => link.addEventListener("click", () => {
  nav.classList.remove("open");
  menuToggle.setAttribute("aria-expanded", "false");
}));

document.querySelector(".language-toggle").addEventListener("click", () => setLanguage(language === "en" ? "es" : "en"));
document.querySelector(".catalog-filters").addEventListener("click", (event) => {
  const button = event.target.closest(".catalog-filter");
  if (!button) return;
  activeFilter = button.dataset.filter;
  renderProductTabs();
  updateProduct(activeProduct);
});

const feedSelector = document.getElementById("feed-selector");
feedSelector.addEventListener("click", (event) => {
  const tab = event.target.closest(".feed-tab");
  if (tab) updateProduct(tab.dataset.product);
});
feedSelector.addEventListener("keydown", (event) => {
  if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
  const tabs = [...feedSelector.querySelectorAll(".feed-tab")];
  const currentIndex = tabs.indexOf(document.activeElement);
  if (currentIndex < 0) return;
  event.preventDefault();
  let nextIndex = event.key === "Home" ? 0 : event.key === "End" ? tabs.length - 1 : currentIndex + (event.key === "ArrowRight" ? 1 : -1);
  nextIndex = (nextIndex + tabs.length) % tabs.length;
  tabs[nextIndex].focus();
  updateProduct(tabs[nextIndex].dataset.product);
});

const breedDialog = document.querySelector(".breed-dialog");
document.querySelectorAll(".breed-card").forEach((card) => card.addEventListener("click", () => {
  const breed = breeds[card.dataset.breed];
  const localized = breed[language];
  document.getElementById("dialog-image").src = breed.image;
  document.getElementById("dialog-image").alt = `${breed.name} rooster`;
  document.getElementById("dialog-country").textContent = breed.country;
  document.getElementById("dialog-title").textContent = breed.name;
  document.getElementById("dialog-text").textContent = localized.text;
  document.getElementById("dialog-traits").innerHTML = localized.traits.map((trait) => `<span>${trait}</span>`).join("");
  breedDialog.showModal();
}));

document.querySelector(".breed-dialog .dialog-close").addEventListener("click", () => breedDialog.close());
document.querySelector(".dialog-quote").addEventListener("click", () => {
  breedDialog.close();
  document.getElementById("quote").scrollIntoView({ behavior: "smooth" });
});

const specDialog = document.querySelector(".spec-dialog");
document.querySelector(".nutrition-button").addEventListener("click", () => specDialog.showModal());
document.querySelector(".spec-close").addEventListener("click", () => specDialog.close());

[breedDialog, specDialog].forEach((dialog) => dialog.addEventListener("click", (event) => {
  const rect = dialog.getBoundingClientRect();
  const outside = event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom;
  if (outside) dialog.close();
}));

document.querySelectorAll('.placeholder-contact a[href="#"]').forEach((link) => link.addEventListener("click", (event) => event.preventDefault()));

const quoteForm = document.querySelector(".quote-form");
quoteForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const name = quoteForm.elements.name;
  const contact = quoteForm.elements.contact;
  [name, contact].forEach((field) => field.classList.remove("invalid"));
  if (!name.value.trim() || !contact.value.trim()) {
    if (!name.value.trim()) name.classList.add("invalid");
    if (!contact.value.trim()) contact.classList.add("invalid");
    quoteForm.querySelector(".form-status").textContent = copy[language].formRequired;
    (!name.value.trim() ? name : contact).focus();
    return;
  }
  quoteForm.querySelector(".form-status").textContent = copy[language].formSuccess;
  quoteForm.querySelector(".submit-button").textContent = language === "en" ? "Prototype confirmed ✓" : "Prototipo confirmado ✓";
});

const revealObserver = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) {
      entry.target.classList.add("visible");
      revealObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.12 });
document.querySelectorAll(".reveal").forEach((element, index) => {
  element.style.transitionDelay = `${Math.min(index % 4, 3) * 80}ms`;
  revealObserver.observe(element);
});

if (matchMedia("(prefers-reduced-motion: reduce)").matches) {
  document.querySelectorAll("video").forEach((video) => video.pause());
}

setLanguage(language);
